/* @lc app=leetcode id=2003 lang=kotlin */
class Solution { fun smallestMissingValueSubtree(parents: IntArray, nums: IntArray): IntArray = IntArray(parents.size) { 1 }.also { res -> nums.indexOf(1).takeIf { it != -1 }?.let { startNode -> mutableSetOf<Int>().let { seen -> Array(parents.size) { mutableListOf<Int>() }.also { adj -> parents.forEachIndexed { i, p -> if (p != -1) adj[p].add(i) } }.let { adj -> object { fun f(u: Int): Unit = if (nums[u] !in seen) seen.add(nums[u]).also { adj[u].forEach { f(it) } } else Unit }.let { dfs -> generateSequence(startNode) { parents[it].takeIf { it != -1 } }.fold(1) { mex, curr -> dfs.f(curr).let { generateSequence(mex) { it + 1 }.first { it !in seen }.also { res[curr] = it } } } } } } } } }